/**
 * Azure DevOps REST API 7.1, through the connection's Named Credential
 * (default RLY_AzureDevOps, URL https://dev.azure.com).
 * Token: personal access token with Code: Read and Build: Read and execute.
 * Repository is organization/project/repository. Workflow file is the pipeline id (a number).
 * Azure Repos has no per-file patch API, so the review screen compares the two versions itself.
 */
public with sharing class RlyAzureDevOpsService extends RlyGitProvider {

    private static final Pattern REPO_PATTERN = Pattern.compile('^[A-Za-z0-9_.-]+/[A-Za-z0-9_. -]+/[A-Za-z0-9_. -]+$');
    private static final String V = 'api-version=7.1';

    private String org;
    private String project;
    private String repoName;

    protected override void init(RlySettings.Connection c) {
        super.init(c);
        List<String> parts = c.repository.trim().split('/');
        this.org = parts[0];
        this.project = parts[1];
        this.repoName = parts[2];
        if (!Pattern.matches('[0-9]{1,9}', c.workflowFile == null ? '' : c.workflowFile.trim())) {
            throw new GitException('For Azure DevOps, set Pipeline on connection ' + c.label + ' to the pipeline id (the number in its URL, definitionId=).');
        }
    }

    public override Pattern repositoryPattern() { return REPO_PATTERN; }
    public override String repositoryHint() { return 'organization/project/repository'; }

    private String git(String path) {
        return '/' + RlyGitProvider.enc(org) + '/' + RlyGitProvider.enc(project) + '/_apis/git/repositories/' + RlyGitProvider.enc(repoName) + path;
    }

    private String web(String path) {
        return 'https://dev.azure.com/' + RlyGitProvider.enc(org) + '/' + RlyGitProvider.enc(project) + '/_git/' + RlyGitProvider.enc(repoName) + path;
    }

    public override Boolean branchExists(String branch) {
        HttpResponse res = send('GET', git('/refs?filter=' + RlyGitProvider.enc('heads/' + branch) + '&' + V), null, null);
        assertOk(res, 'Branch lookup');
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('value')) {
            if (((Map<String, Object>) o).get('name') == 'refs/heads/' + branch) {
                return true;
            }
        }
        return false;
    }

    public override List<String> listBranches() {
        HttpResponse res = send('GET', git('/refs?filter=heads/&$top=1000&' + V), null, null);
        assertOk(res, 'Branch list');
        List<String> names = new List<String>();
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('value')) {
            names.add(String.valueOf(((Map<String, Object>) o).get('name')).removeStart('refs/heads/'));
        }
        return names;
    }

    /** ref is a branch name, or a commit id (40 hex characters). */
    private static String versionParams(String ref) {
        Boolean isCommit = ref != null && Pattern.matches('[0-9a-f]{40}', ref);
        return '&versionDescriptor.version=' + RlyGitProvider.enc(ref) + '&versionDescriptor.versionType=' + (isCommit ? 'commit' : 'branch');
    }

    public override String getFileRaw(String filePath, String ref) {
        HttpResponse res = send('GET', git('/items?path=' + RlyGitProvider.enc('/' + filePath) + versionParams(ref)
            + '&includeContent=true&$format=octetStream&' + V), null, null);
        if (res.getStatusCode() == 404) {
            return null;
        }
        assertOk(res, 'File read');
        return res.getBody();
    }

    public override List<Entry> listDir(String folderPath, String ref) {
        List<Entry> out = new List<Entry>();
        String scope = '/' + folderPath;
        HttpResponse res = send('GET', git('/items?scopePath=' + RlyGitProvider.enc(scope) + '&recursionLevel=OneLevel' + versionParams(ref) + '&' + V), null, null);
        if (res.getStatusCode() == 404) {
            return out;
        }
        assertOk(res, 'Folder read');
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('value')) {
            Map<String, Object> m = (Map<String, Object>) o;
            String itemPath = String.valueOf(m.get('path'));
            if (itemPath != scope) {
                out.add(RlyGitProvider.entry(itemPath.substringAfterLast('/'), m.get('isFolder') == true));
            }
        }
        return out;
    }

    public override Comparison compare(String baseRef, String head) {
        HttpResponse res = send('GET', git('/diffs/commits?baseVersion=' + RlyGitProvider.enc(baseRef) + '&baseVersionType=branch&targetVersion='
            + RlyGitProvider.enc(head) + '&targetVersionType=branch&$top=300&' + V), null, null);
        if (res.getStatusCode() == 404) {
            throw new GitException('Branch ' + head + ' or ' + baseRef + ' was not found.');
        }
        assertOk(res, 'Compare');
        Map<String, Object> body = (Map<String, Object>) RlyGitProvider.parse(res);
        Comparison c = new Comparison();
        c.aheadBy = RlyGitProvider.toInt(body.get('aheadCount'));
        c.behindBy = RlyGitProvider.toInt(body.get('behindCount'));
        c.url = web('/branchCompare?baseVersion=GB' + RlyGitProvider.enc(baseRef) + '&targetVersion=GB' + RlyGitProvider.enc(head));
        for (Object o : (List<Object>) body.get('changes')) {
            Map<String, Object> ch = (Map<String, Object>) o;
            Map<String, Object> item = (Map<String, Object>) ch.get('item');
            if (item != null && item.get('isFolder') != true) {
                c.files.add(status(String.valueOf(ch.get('changeType'))) + '  ' + String.valueOf(item.get('path')).removeStart('/'));
            }
        }
        return c;
    }

    /** Runs the pipeline on the workflow branch; empty values are sent as '-' because Azure requires a value. */
    public override Started startPipeline(Map<String, String> inputs) {
        Map<String, String> params = new Map<String, String>();
        for (String k : inputs.keySet()) {
            params.put(k, String.isBlank(inputs.get(k)) ? '-' : inputs.get(k));
        }
        Map<String, Object> body = new Map<String, Object>{
            'resources' => new Map<String, Object>{ 'repositories' => new Map<String, Object>{
                'self' => new Map<String, Object>{ 'refName' => 'refs/heads/' + conn.workflowRef } } },
            'templateParameters' => params
        };
        HttpResponse res = send('POST', '/' + RlyGitProvider.enc(org) + '/' + RlyGitProvider.enc(project) + '/_apis/pipelines/' + conn.workflowFile.trim()
            + '/runs?' + V, JSON.serialize(body), null);
        assertOk(res, 'Pipeline start');
        Map<String, Object> m = (Map<String, Object>) RlyGitProvider.parse(res);
        Started s = new Started();
        s.runId = String.valueOf(m.get('id'));
        s.url = webLink(m);
        return s;
    }

    public override Run findRun(String releaseName, String runMode, String knownRunId) {
        if (String.isBlank(knownRunId)) {
            return null;
        }
        HttpResponse res = send('GET', '/' + RlyGitProvider.enc(org) + '/' + RlyGitProvider.enc(project) + '/_apis/pipelines/' + conn.workflowFile.trim()
            + '/runs/' + RlyGitProvider.enc(knownRunId) + '?' + V, null, null);
        if (res.getStatusCode() == 404) {
            return null;
        }
        assertOk(res, 'Pipeline lookup');
        Map<String, Object> m = (Map<String, Object>) RlyGitProvider.parse(res);
        String state = String.valueOf(m.get('state'));
        String result = m.get('result') == null ? null : String.valueOf(m.get('result'));
        Run run = new Run();
        run.id = knownRunId;
        run.url = webLink(m);
        run.createdAt = RlyGitProvider.parseTime(m.get('createdDate'));
        run.status = state == 'completed' ? 'completed' : state == 'inProgress' ? 'in_progress' : 'queued';
        run.conclusion = state != 'completed' ? null : result == 'succeeded' ? 'success' : result == 'canceled' ? 'cancelled' : 'failure';
        return run;
    }

    public override PullRequest findPullRequest(String branch, String target) {
        Map<String, Object> m = prRecord(branch, target);
        if (m == null) {
            return null;
        }
        PullRequest pr = new PullRequest();
        pr.num = RlyGitProvider.toInt(m.get('pullRequestId'));
        pr.url = web('/pullrequest/' + pr.num);
        String status = String.valueOf(m.get('status'));
        pr.merged = status == 'completed';
        pr.state = status == 'active' ? 'open' : 'closed';
        return pr;
    }

    private Map<String, Object> prRecord(String branch, String target) {
        HttpResponse res = send('GET', git('/pullrequests?searchCriteria.sourceRefName=' + RlyGitProvider.enc('refs/heads/' + branch)
            + '&searchCriteria.targetRefName=' + RlyGitProvider.enc('refs/heads/' + target) + '&searchCriteria.status=all&$top=1&' + V), null, null);
        assertOk(res, 'Pull request lookup');
        List<Object> rows = (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('value');
        return rows == null || rows.isEmpty() ? null : (Map<String, Object>) rows[0];
    }

    /** The files the pull request changes, between its last merge source and target commits. */
    public override List<PrFile> pullFiles(Integer prNumber, String target, String branch) {
        HttpResponse one = send('GET', git('/pullrequests/' + prNumber + '?' + V), null, null);
        assertOk(one, 'Pull request read');
        Map<String, Object> m = (Map<String, Object>) RlyGitProvider.parse(one);
        String sourceCommit = commitOf(m.get('lastMergeSourceCommit'));
        String targetCommit = commitOf(m.get('lastMergeTargetCommit'));
        String baseVersion = targetCommit != null ? targetCommit : target;
        String headVersion = sourceCommit != null ? sourceCommit : branch;
        String types = (sourceCommit != null ? 'commit' : 'branch');
        HttpResponse res = send('GET', git('/diffs/commits?baseVersion=' + RlyGitProvider.enc(baseVersion) + '&baseVersionType=' + types
            + '&targetVersion=' + RlyGitProvider.enc(headVersion) + '&targetVersionType=' + types + '&diffCommonCommit=true&$top=300&' + V), null, null);
        assertOk(res, 'Pull request files');
        List<PrFile> out = new List<PrFile>();
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('changes')) {
            Map<String, Object> ch = (Map<String, Object>) o;
            Map<String, Object> item = (Map<String, Object>) ch.get('item');
            if (item == null || item.get('isFolder') == true) {
                continue;
            }
            PrFile f = new PrFile();
            f.filename = String.valueOf(item.get('path')).removeStart('/');
            f.status = status(String.valueOf(ch.get('changeType')));
            f.additions = 0;
            f.deletions = 0;
            f.patch = '';
            f.truncated = false;
            f.baseRef = baseVersion;
            f.headRef = headVersion;
            out.add(f);
        }
        return out;
    }

    private static String commitOf(Object o) {
        if (!(o instanceof Map<String, Object>)) {
            return null;
        }
        Object id = ((Map<String, Object>) o).get('commitId');
        return id == null ? null : String.valueOf(id);
    }

    private static String webLink(Map<String, Object> m) {
        Map<String, Object> links = (Map<String, Object>) m.get('_links');
        Map<String, Object> w = links == null ? null : (Map<String, Object>) links.get('web');
        return w == null ? null : String.valueOf(w.get('href'));
    }

    private static String status(String changeType) {
        String t = changeType == null ? '' : changeType.toLowerCase();
        return t.contains('add') ? 'added' : t.contains('delete') ? 'removed' : t.contains('rename') ? 'renamed' : 'modified';
    }
}
